// Valida que la notificación venga de Mercado Pago (header x-signature, HMAC-SHA256).
// Doc: Mercado Pago -> Notificaciones -> Webhooks -> Validar origen.
const crypto = require('crypto');
const { headers = {}, query = {}, body = {} } = $input.first().json;

const tipo = body.type || query.type || query.topic;
if (tipo !== 'payment') return []; // otros eventos (merchant_order, etc.): se ignoran

const dataId = String(query['data.id'] ?? body?.data?.id ?? '');
const firma = headers['x-signature'] || '';
const requestId = headers['x-request-id'] || '';
const partes = Object.fromEntries(
  firma.split(',').map((p) => p.trim().split('=').map((s) => s.trim()))
);
const { ts, v1 } = partes;
if (!dataId || !ts || !v1) throw new Error('Notificación sin firma o sin data.id');

// Si el id es alfanumérico, Mercado Pago pide usarlo en minúsculas.
const id = /^[a-z0-9]+$/i.test(dataId) ? dataId.toLowerCase() : dataId;
let manifest = `id:${id};`;
if (requestId) manifest += `request-id:${requestId};`;
manifest += `ts:${ts};`;

const esperado = crypto
  .createHmac('sha256', $env.MP_WEBHOOK_SECRET)
  .update(manifest)
  .digest('hex');
const ok =
  esperado.length === v1.length &&
  crypto.timingSafeEqual(Buffer.from(esperado), Buffer.from(v1));
if (!ok) throw new Error('Firma de Mercado Pago inválida');

return [{ json: { paymentId: dataId } }];

// Deja solo los datos que le importan al dueño del negocio.
return $input.all().map(({ json: p }) => {
  const nombre = [p.payer?.first_name, p.payer?.last_name].filter(Boolean).join(' ');
  const monto = new Intl.NumberFormat('es-AR', {
    style: 'currency',
    currency: p.currency_id || 'ARS',
  }).format(p.transaction_amount);
  return {
    json: {
      id_pago: String(p.id),
      fecha: p.date_approved,
      monto: p.transaction_amount,
      monto_texto: monto,
      medio: p.payment_method_id,
      pagador: nombre || p.payer?.email || 'Cliente',
      descripcion: p.description || 'Sin descripción',
      referencia: p.external_reference || '',
    },
  };
});

